            "title": "The Secret Garden of Class Five",
            "level": "beginner",
            "levelcefr": "A1",
            "cover": "https://images.pexels.com/photos/37639780/pexels-photo-37639780.jpeg?auto=compress&cs=tinysrgb&w=900",
