            "id": 141,
            "lang": "en",
            "title": "The Cartographer's Last Map",
            "level": "advanced",
            "levelcefr": "C1",
            "cover": "https://images.pexels.com/photos/3837487/pexels-photo-3837487.jpeg?auto=compress&cs=tinysrgb&w=900",
            "coverType": "image",
