            "title": "The Silence of the Studio",
            "level": "advanced",
            "levelcefr": "C1",
            "cover": "https://images.pexels.com/photos/6925325/pexels-photo-6925325.jpeg?auto=compress&cs=tinysrgb&w=900",
            "coverType": "image",
